object BrakePedalQualificationOwner_Api {
  // assume pedalStartCondition
  //   brake pedal report is a current snapshot of TYPE-02
  @strictpure def pedalStartCondition(brake_pedal_report: Protected_Start_Power_Supervisor.BrakePedalReport): B =
    brake_pedal_report.status == Validity.Valid |
      brake_pedal_report.status == Validity.Invalid
}

